    quests_in_day = tt_cards_constants.PREMIUM_PLAYER_SPEED * quest_card_probability
    power_for_quest = statistics.get_power_for_quest(places_storage.places.expected_minimum_quest_distance()) * c.EXPECTED_HERO_QUEST_POWER_MODIFIER
    return int(math.ceil(quests_in_day * power_for_quest * tt_clans_constants.FIGHTERS_TO_EMISSARY))

def get_groups(self):
    result = self._make_requests_to_api('groups?all_available=true', paginated=True)
    return sorted(map(lambda x: x['full_path'], result))

def predicate(self, predicate, object, depth=1):
    writer = self.writer
    store = self.store
    writer.push(predicate)
    if isinstance(object, Literal):
        attributes = ''
        if object.language:
            writer.attribute(XMLLANG, object.language)
        if object.datatype:
            writer.attribute(RDF.datatype, object.datatype)
        writer.text(object)
    elif object in self.__serialized or not (object, None, None) in store:
        if isinstance(object, BNode):
            if more_than(store.triples((None, None, object)), 0):
                writer.attribute(RDF.nodeID, fix(object))
        else:
            writer.attribute(RDF.resource, self.relativize(object))
    elif first(store.objects(object, RDF.first)):
        import logging
        logging.warning('Assertions on object other than RDF.first and RDF.rest are ignored, including RDF.List: %s', object)
        collection = object
        self.__serialized[object] = 1
        writer.attribute(RDF.parseType, 'Collection')
        col = Collection(store, object)
        for item in col:
            if isinstance(item, URIRef):
                self.forceRDFAbout.add(item)
            self.subject(item)
            if not isinstance(item, URIRef):
                self.__serialized[item] = 1
    elif first(store.triples_choices((object, RDF.type, [OWL_NS.Class, RDFS.Class]))) and isinstance(object, URIRef):
        writer.attribute(RDF.resource, self.relativize(object))
    elif depth <= self.max_depth:
        self.subject(object, depth + 1)
    elif isinstance(object, BNode):
        if not object in self.__serialized and (object, None, None) in store and (len(list(store.subjects(object=object))) == 1):
            self.subject(object, depth + 1)
        else:
            writer.attribute(RDF.nodeID, fix(object))
    else:
        writer.attribute(RDF.resource, self.relativize(object))
    writer.pop(predicate)

def hashpass(self, username):
    secret_salt = settings.SECRET_KEY.translate(None, string.punctuation)
    password = crypt.crypt(username, secret_salt)
    if not password:
        raise Exception('Failed to hash password, check the secret_salt')
    return password

def _serialize_stock(offer_id: int, stock: Optional[CollectiveStock]=None) -> dict:
    if stock:
        return {'id': humanize(stock.id), 'offerId': humanize(offer_id), 'hasBookingLimitDatetimePassed': stock.hasBookingLimitDatetimePassed, 'remainingQuantity': 1, 'beginningDatetime': stock.beginningDatetime}
    return {'id': humanize(0), 'offerId': humanize(offer_id), 'hasBookingLimitDatetimePassed': False, 'remainingQuantity': 1, 'beginningDatetime': datetime(year=2030, month=1, day=1)}

def __init__(self, obj=None, token=None):
    if token:
        self.token = token
        self.is_trusted_system = True
        shared_secret = os.getenv(SHARED_SECRET_ENV_VAR)
        if not shared_secret:
            logger.warning('%s environment variable is not set', SHARED_SECRET_ENV_VAR)
        if self.token != shared_secret:
            raise ValueError('Invalid credentials')
        threadctx.account_number = '<<TRUSTED IDENTITY>>'
    elif obj:
        self.is_trusted_system = False
        self.account_number = obj.get('account_number')
        self.auth_type = obj.get('auth_type')
        self.identity_type = obj.get('type')
        if not self.account_number:
            raise ValueError('The account_number is mandatory.')
        elif not self.identity_type or self.identity_type not in IdentityType.__members__.values():
            raise ValueError('Identity type invalid or missing in provided Identity')
        elif self.auth_type and self.auth_type not in AuthType.__members__.values():
            raise ValueError(f'The auth_type {self.auth_type} is invalid')
        if self.identity_type == IdentityType.USER:
            self.user = obj.get('user')
        elif self.identity_type == IdentityType.SYSTEM:
            self.system = obj.get('system')
            if not self.system:
                raise ValueError('The identity.system field is mandatory for system-type identities')
            elif not self.system.get('cert_type'):
                raise ValueError('The cert_type field is mandatory for system-type identities')
            elif self.system.get('cert_type') not in CertType.__members__.values():
                raise ValueError(f"The cert_type {self.system.get('cert_type')} is invalid.")
            elif not self.system.get('cn'):
                raise ValueError('The cn field is mandatory for system-type identities')
        threadctx.account_number = obj['account_number']
    else:
        raise ValueError('Neither the account_number or token has been set')

def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    exprs = [self._parse_assignment_expression(inTemplate=inTemplate)]
    while True:
        self.skip_ws()
        if not self.skip_string(','):
            break
        exprs.append(self._parse_assignment_expression(inTemplate=inTemplate))
    if len(exprs) == 1:
        return exprs[0]
    else:
        return ASTCommaExpr(exprs)

