def _processMessage(self, msg):
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if wspaces > 1 and qmarks > 0 or wspaces > 2 or qmarks > 1:
        res = 'ERROR: Cannot parse this command\n'
    elif qmarks:
        if tokens[0] == '*IDN?':
            res = IDN + '\n'
        elif tokens[0] == 'PWR?':
            pin = int(tokens[1])
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                ans = self._i2crcv >> pin & MASK
                res = str(ans) + '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == 'PWR':
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                self._i2crcv = self._i2crcv & ~(1 << pin) | val << pin & 1 << pin
                res = '\n'
        elif tokens[0] == 'WMEM':
            id = tokens[1]
            address = tokens[2]
            data = tokens[3]
            self.writeMemory(id, address, data)
            res = '\n'
        elif tokens[0] == 'RMEM':
            id = tokens[1]
            address = tokens[2]
            length = int(tokens[3])
            res = self.readMemory(id, address, length) + '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    else:
        res = 'ERROR: Cannot parse this command\n'
    if res is not None:
        self._output_buf += res

def _processMessage(self, msg):
    res = b''
    wspaces = msg.count(b' ')
    qmarks = msg.count(b'?')
    tokens = msg.split()
    if wspaces > 1 and qmarks > 0 or wspaces > 3 or qmarks > 1:
        res = b'ERROR: Cannot parse this command\n'
    elif qmarks:
        if tokens[0] == b'*IDN?':
            res = IDN + b'\n'
        elif tokens[0] == b'PWR?':
            pin = int(tokens[1])
            if pin < 0 or pin > 7:
                res = b'ERROR: Out of range pin number\n'
            else:
                ans = self._i2crcv >> pin & MASK
                res = b'%d\n' % ans
        else:
            res = b'ERROR: Cannot parse this command\n'
    elif wspaces:
        if tokens[0] == b'PWR':
            pin = int(tokens[1])
            val = int(tokens[2])
            if pin < 0 or pin > 7:
                res = b'ERROR: Out of range pin number\n'
            else:
                self._i2crcv = self._i2crcv & ~(1 << pin) | val << pin & 1 << pin
                res = b'\n'
        elif tokens[0] == b'WMEM':
            id = tokens[1]
            address = tokens[2]
            data = tokens[3]
            if len(id) % 2 == 1:
                res = b'ERROR: Invalid number of hexadecimal id characters. Must be an even number.\n'
            elif len(address) % 2 == 1:
                res = b'ERROR: Invalid number of hexadecimal address characters. Must be an even number.\n'
            elif len(data) % 2 == 1:
                res = b'ERROR: Invalid number of hexadecimal data characters. Must be an even number.\n'
            else:
                try:
                    id_ind = self._ids.index(id)
                    addr = int(address, 16)
                    for i in range(len(data) // 2):
                        self._mem[id_ind, addr + i] = data[i * 2:i * 2 + 2]
                    res = b'\n'
                except ValueError:
                    res = b'ERROR: Unknown id\n'
        elif tokens[0] == b'RMEM':
            id = tokens[1]
            address = tokens[2]
            length = tokens[3]
            if len(id) % 2 == 1:
                res = b'ERROR: Invalid number of hexadecimal id characters. Must be an even number.\n'
            elif len(address) % 2 == 1:
                res = b'ERROR: Invalid number of hexadecimal address characters. Must be an even number.\n'
            else:
                try:
                    id_ind = self._ids.index(id)
                    addr = int(address, 16)
                    length_int = int(length)
                    data_bytes = b''
                    for i in range(length_int):
                        data_bytes += self._mem[id_ind, addr + i]
                    res = data_bytes + b'\n'
                except ValueError:
                    res = b'ERROR: Unknown id\n'
        else:
            res = b'ERROR: Cannot parse this command\n'
    else:
        res = b'ERROR: Cannot parse this command\n'
    if res is not None:
        self._output_buf += res

