def save_bearer_token(self, token, request, *args, **kwargs):
    previous_valid_tokens = AccessToken.objects.filter(user=request.user, application=request.client).filter(expires__gt=timezone.now()).order_by('-expires')
    if not request.refresh_token and previous_valid_tokens.exists():
        for access_token in previous_valid_tokens:
            if access_token.allow_scopes(token['scope'].split()):
                token['access_token'] = access_token.token
                expires_in = access_token.expires - timezone.now()
                token['expires_in'] = math.floor(expires_in.total_seconds())
                if hasattr(access_token, 'refresh_token'):
                    token['refresh_token'] = access_token.refresh_token.token
                return
    if request.refresh_token:
        try:
            RefreshToken.objects.get(token=request.refresh_token).revoke()
        except RefreshToken.DoesNotExist:
            logger.error('Refresh token does not exist: %s', request.refresh_token)
    expires = timezone.now() + timedelta(seconds=token['expires_in'])
    if request.grant_type == 'client_credentials':
        request.user = None
    access_token = AccessToken(user=request.user, scope=token['scope'], expires=expires, token=token['access_token'], application=request.client)
    access_token.save()
    if 'refresh_token' in token:
        refresh_token = RefreshToken(user=request.user, token=token['refresh_token'], application=request.client, access_token=access_token)
        refresh_token.save()

def create_force_refresh_endpoint(input_type: InputType, job_type: str, hf_endpoint: str, hf_token: Optional[str]=None, external_auth_url: Optional[str]=None, organization: Optional[str]=None) -> Endpoint:

    async def force_refresh_endpoint(request: Request) -> Response:
        try:
            dataset = request.query_params.get('dataset')
            if not are_valid_parameters([dataset]) or not dataset:
                raise MissingRequiredParameterError("Parameter 'dataset' is required")
            if input_type == 'dataset':
                config = None
                split = None
            elif input_type == 'config':
                config = request.query_params.get('config')
                split = None
                if not are_valid_parameters([config]):
                    raise MissingRequiredParameterError("Parameter 'config' is required")
            else:
                config = request.query_params.get('config')
                split = request.query_params.get('split')
                if not are_valid_parameters([config, split]):
                    raise MissingRequiredParameterError("Parameters 'config' and 'split' are required")
            logging.info(f'/force-refresh{job_type}, dataset={dataset}, config={config}, split={split}')
            auth_check(external_auth_url=external_auth_url, request=request, organization=organization)
            revision = get_dataset_git_revision(dataset=dataset, hf_endpoint=hf_endpoint, hf_token=hf_token)
            Queue().upsert_job(job_type=job_type, dataset=dataset, config=config, split=split, revision=revision)
            return get_json_ok_response({'status': 'ok'}, max_age=0)
        except CustomError as e:
            return get_json_admin_error_response(e, max_age=0)
        except Exception as e:
            return get_json_admin_error_response(UnexpectedError('Unexpected error.', e), max_age=0)
    return force_refresh_endpoint

def transform(self, X, y=None):
    X = check_array(X)
    if self.mean_ is not None:
        X = X - self.mean_
    X = safe_sparse_dot(X, self.components_.T)
    return X

